using Gtk 4.0;
using Adw 1;

Adw.AboutDialog about_dialog {
  application-name: "Iotas";
  developer-name: "Chris Heywood";
  copyright: "© 2022 Chris Heywood";
  website: "https://gitlab.gnome.org/World/iotas";
  license-type: gpl_3_0;
  issue-url: "https://gitlab.gnome.org/World/iotas/-/issues";

  // Translators: Add your name to the translator credits list
  translator-credits: _("translator-credits");
}

// SPDX-FileCopyrightText: 2022 Chris Heywood
//
// SPDX-License-Identifier: GPL-3.0-or-later
using Gtk 4.0;
using Adw 1;

template $CategoryHeaderBar: Adw.Bin {
  styles [
    "background",
  ]

  Adw.HeaderBar {
    show-start-title-buttons: false;
    show-end-title-buttons: false;
    show-back-button: false;
    hexpand: true;

    [start]
    Button {
      // Translators: Button
      tooltip-text: _("Revert Changes");
      icon-name: "edit-undo-symbolic";
      clicked => $_on_abort();
    }

    [title]
    Adw.Clamp {
      hexpand: true;

      Box {
        orientation: horizontal;
        spacing: 12;

        Entry _entry {
          hexpand: true;
          max-length: 500;
          primary-icon-name: "folder-symbolic";
          activate => $_on_entry_activated();

          styles [
            "category-selector",
          ]

          completion: EntryCompletion _completion {
            inline-completion: true;
            minimum-key-length: 0;
            text-column: 0;
          };

          EventControllerKey {
            propagation-phase: capture;
            key-pressed => $_on_entry_key_pressed();
          }
        }

        Button _apply_button {
          // Translators: Button
          label: _("Apply");

          // Translators: Button tooltip
          tooltip-text: _("Apply Changes");

          clicked => $_on_apply();

          styles [
            "suggested-action",
          ]
        }
      }
    }

    [end]
    Button _clear_button {
      // Translators: Button
      tooltip-text: _("Clear and Apply");
      icon-name: "eraser3-symbolic";
      clicked => $_on_clear();

      styles [
        "destructive-action",
      ]
    }
  }
}

// SPDX-FileCopyrightText: 2022 Chris Heywood
//
// SPDX-License-Identifier: GPL-3.0-or-later
using Gtk 4.0;
using Adw 1;

menu menu {
  section {
    item {
      custom: "theme";
    }
  }

  section {
    item {
      custom: "fontsize";
    }
  }

  section {
    item {
      // Translators: Menu item
      label: _("Focus Mode");
      action: "editor.focus-mode";
    }
  }

  section {
    item {
      // Translators: Menu item
      label: _("Find and Replace…");
      action: "editor.enter-search";
    }

    item {
      // Translators: Menu item
      label: _("Jump To…");
      action: "editor.show-outline";
    }
  }

  section {
    item {
      // Translators: Menu item
      label: _("Edit Title…");
      action: "editor.rename";
    }

    item {
      // Translators: Menu item
      label: _("Change Category…");
      action: "editor.edit-category";
    }

    item {
      // Translators: Menu item
      label: _("Delete");
      action: "editor.delete-note";
    }
  }

  section {
    item {
      // Translators: Menu item
      label: _("Export…");
      action: "editor.export-note";
    }
  }
}

EntryCompletion _category_completion {
  inline-completion: true;
  minimum-key-length: 0;
  text-column: 0;
}

template $Editor: Adw.Bin {
  name: "Editor";

  Adw.ToastOverlay _toast_overlay {
    child: Overlay {
      vexpand: true;

      [overlay]
      Adw.Bin {
        valign: start;

        Revealer _top_bar_revealer {
          valign: start;
          halign: fill;
          hexpand: true;
          transition-type: crossfade;
          transition-duration: 400;
          name: "EditorTopBarRevealer";

          child: Stack _headerbar_stack {
            styles [
              "background",
            ]

            Adw.HeaderBar _main_header_bar {
              hexpand: true;
              show-back-button: false;

              [start]
              Button {
                // Translators: Description, tooltip
                tooltip-text: _("Back to Notes");
                icon-name: "go-previous-symbolic";
                action-name: "editor.go-back-or-cancel";
              }

              [title]
              Box {
                orientation: horizontal;

                Button _title_button {
                  action-name: "editor.rename";

                  styles [
                    "note-title-header",
                  ]

                  CenterBox {
                    [center]
                    Label _title_label {
                      ellipsize: end;
                    }

                    [start]
                    Label _is_dirty {
                      label: "•";
                      margin-end: 6;
                    }
                  }

                }

                Image _read_only_image {
                  // Translators: Description, help
                  tooltip-text: _("Note is Read-Only");
                  visible: false;
                  icon-name: "readonly-symbolic";
                }
              }

              [end]
              MenuButton _menu_button {
                // Translators: Description, tooltip
                tooltip-text: _("Editor Menu");
                icon-name: "view-more-symbolic";
                menu-model: menu;
              }

              [end]
              Stack _render_edit_button_stack {
                Button _render_button {
                  // Translators: Description, tooltip
                  tooltip-text: _("Toggle Markdown Render");
                  icon-name: "eye-open-negative-filled-symbolic";
                  action-name: "editor.toggle-render";
                }

                Button _edit_button {
                  // Translators: Description, tooltip
                  tooltip-text: _("Edit Note");
                  icon-name: "edit-symbolic";
                  action-name: "editor.toggle-render";
                }
              }
            }

            $EditorRenameHeaderBar _rename_header_bar {}

            $EditorSearchHeaderBar _search_header_bar {}

            $CategoryHeaderBar _category_header_bar {}

            $RenderSearchHeaderBar _render_search_header_bar {}
          };
        }

        EventControllerMotion {
          enter => $_on_top_margin_motion();
          motion => $_on_top_margin_motion();
        }

        GestureClick {
          button: 0;
          touch-only: true;
          pressed => $_on_top_margin_click();
        }
      }

      [overlay]
      Adw.Bin {
        valign: end;

        Revealer _bottom_bar_revealer {
          halign: fill;
          hexpand: true;
          transition-type: crossfade;
          transition-duration: 400;
          name: "EditorBottomBarRevealer";

          child: $FormattingHeaderBar _formatting_header_bar {};
        }

        EventControllerMotion {
          enter => $_on_bottom_margin_motion();
          motion => $_on_bottom_margin_motion();
        }

        GestureClick {
          button: 0;
          touch-only: true;
          pressed => $_on_bottom_margin_click();
        }
      }

      Stack _render_edit_stack {
        ScrolledWindow _editor_scrolledwin {
          $EditorTextView _sourceview {
            name: "EditView";
            halign: fill;
            vexpand: true;
            margin-start: 10;
            margin-end: 10;
            bottom-margin: 64;
            wrap-mode: word_char;
            accepts-tab: false;
            input-hints: word_completion;

            styles [
              "editor-textview",
            ]

            EventControllerKey {
              propagation-phase: capture;
              key-pressed => $_on_key_pressed();
            }

            GestureSingle {
              end => $_on_editor_single_click();
            }
          }

          styles [
            "editor",
          ]
        }

        Adw.StatusPage _render_loading {
          // Translators: Description, help
          title: _("Render Engine Loading");
          icon-name: "content-loading-symbolic";
        }
      }
    };
  }

  GestureClick {
    button: 8;
    pressed => $_on_mouse_back_button_click();
  }
}

// SPDX-FileCopyrightText: 2022 Chris Heywood
//
// SPDX-License-Identifier: GPL-3.0-or-later
using Gtk 4.0;
using Adw 1;

template $EditorRenameHeaderBar: Adw.Bin {
  styles [
    "background",
  ]

  Adw.HeaderBar {
    show-start-title-buttons: false;
    show-end-title-buttons: false;
    show-back-button: false;
    hexpand: true;

    [start]
    Button {
      // Translators: Description, tooltip
      tooltip-text: _("Revert Changes");
      icon-name: "edit-undo-symbolic";
      clicked => $_abort_rename();
    }

    [title]
    Adw.Clamp {
      hexpand: true;

      Box {
        orientation: horizontal;
        spacing: 12;

        Entry _entry {
          hexpand: true;
          max-length: 500;
          activate => $_on_entry_activated();
          changed => $_on_entry_changed();
        }

        Button _apply_button {
          // Translators: Button
          label: _("Apply");

          // Translators: Description, tooltip
          tooltip-text: _("Apply Changes");

          clicked => $_on_apply_pressed();

          styles [
            "suggested-action",
          ]
        }
      }
    }
  }
}

// SPDX-FileCopyrightText: 2022 Chris Heywood
//
// SPDX-License-Identifier: GPL-3.0-or-later
using Gtk 4.0;

template $EditorSearchEntry: Box {
  name: "EditorSearchEntry";

  Image {
    icon-name: "edit-find-symbolic";
  }

  Text text {
    // Translators: Placeholder text
    placeholder-text: _("Find");
    hexpand: true;
    vexpand: true;
    activate => $_on_activate();
  }

  Label _info {
    xalign: 1;

    styles [
      "numeric",
    ]
  }
}

// SPDX-FileCopyrightText: 2022 Chris Heywood
//
// SPDX-License-Identifier: GPL-3.0-or-later
using Gtk 4.0;
using Adw 1;

template $EditorSearchHeaderBar: Box {
  orientation: vertical;

  styles [
    "background",
  ]

  Adw.HeaderBar {
    show-start-title-buttons: false;
    show-end-title-buttons: false;
    show-back-button: false;
    hexpand: true;

    [start]
    Button {
      // Translators: Description, tooltip
      tooltip-text: _("Back");
      icon-name: "go-previous-symbolic";
      action-name: "editor.go-back-or-cancel";
      valign: start;
    }

    [title]
    Adw.Clamp {
      hexpand: true;

      Box {
        orientation: vertical;

        Box {
          orientation: horizontal;
          spacing: 12;

          $EditorSearchEntry _search_entry {
            css-name: "entry";
            hexpand: true;
            width-request: 150;
            activate => $_on_search_entry_activate();
          }

          Button _backward_button {
            // Translators: Description, tooltip
            tooltip-text: _("Previous Match");
            icon-name: "up-large-symbolic";
            action-name: "editor-search.backward";
          }

          Button _forward_button {
            // Translators: Description, tooltip
            tooltip-text: _("Next Match");
            icon-name: "down-large-symbolic";
            action-name: "editor-search.forward";
          }
        }

        Revealer _revealer {
          reveal-child: false;
          hexpand: true;

          Box {
            hexpand: true;
            orientation: horizontal;
            spacing: 6;

            Entry _replace_entry {
              // Translators: Placeholder text
              placeholder-text: _("Replace");
              margin-top: 6;
              hexpand: true;
              primary-icon-name: "edit-find-replace-symbolic";
              width-request: 150;
              activate => $_on_replace_entry_activate();
            }

            Button {
              // Translators: Button
              label: _("Replace");
              margin-top: 6;
              action-name: "editor-search.replace";

              styles [
                "suggested-action",
              ]
            }
          }
        }
      }
    }

    [end]
    ToggleButton _replace_toggle {
      icon-name: "edit-find-replace-symbolic";
      action-name: "editor-search.toggle-replace";
      valign: start;
    }
  }
}

// SPDX-FileCopyrightText: 2022 Chris Heywood
//
// SPDX-License-Identifier: GPL-3.0-or-later
using Gtk 4.0;
using Adw 1;

template $ExportDialog: Adw.Dialog {
  content-width: 510;

  Adw.ToolbarView {
    [top]
    Stack _headerbar_stack {
      Adw.HeaderBar _format_headerbar {
        decoration-layout: "None";
        show-start-title-buttons: false;
        show-end-title-buttons: false;

        title-widget: Adw.WindowTitle {};

        [start]
        Button _cancel_button {
          // Translators: Button
          label: _("Cancel");
          clicked => $_on_cancel();
        }

        [title]
        Label {
          // Translators: Title
          label: _("Export As…");
          ellipsize: end;

          styles [
            "title",
          ]
        }
      }

      Adw.HeaderBar _checking_attachments_headerbar {
        decoration-layout: "None";
        show-start-title-buttons: false;
        show-end-title-buttons: false;

        title-widget: Adw.WindowTitle {};

        [start]
        Button {
          // Translators: Button
          label: _("Cancel");
          clicked => $_on_cancel();
        }

        [title]
        Label {
          // Translators: Title
          label: _("Checking Attachments…");
          ellipsize: end;

          styles [
            "title",
          ]
        }
      }

      Adw.HeaderBar _downloading_headerbar {
        decoration-layout: "None";
        show-start-title-buttons: false;
        show-end-title-buttons: false;

        title-widget: Adw.WindowTitle {};

        [start]
        Button {
          // Translators: Button
          label: _("Cancel");
          clicked => $_on_cancel();
        }
      }

      Adw.HeaderBar _exporting_headerbar {
        decoration-layout: "None";
        show-start-title-buttons: false;
        show-end-title-buttons: false;

        title-widget: Adw.WindowTitle {};

        [start]
        Button {
          // Translators: Button
          label: _("Cancel");
          clicked => $_on_cancel();
        }

        [title]
        Label {
          // Translators: Title
          label: _("Exporting…");
          ellipsize: end;

          styles [
            "title",
          ]
        }
      }

      Adw.HeaderBar _success_headerbar {
        decoration-layout: "None";
        show-start-title-buttons: false;
        show-end-title-buttons: false;

        title-widget: Adw.WindowTitle {};

        [start]
        Button {
          // Translators: Button
          label: _("Close");
          clicked => $_on_cancel();
        }

        [end]
        Button _show_button {
          // Translators: Button
          label: _("Show");
          clicked => $_on_show_clicked();

          styles [
            "suggested-action",
          ]
        }
      }

      Adw.HeaderBar _failure_headerbar {
        decoration-layout: "None";
        show-start-title-buttons: false;
        show-end-title-buttons: false;

        [start]
        Button {
          // Translators: Button
          label: _("Close");
          clicked => $_on_cancel();
        }

        [title]
        Label _failure_headerbar_label {
          ellipsize: end;

          styles [
            "title",
          ]
        }
      }
    }

    content: Stack _main_stack {
      transition-type: slide_left;
      vexpand: true;

      Adw.Clamp {
        maximum-size: 300;

        Box {
          orientation: vertical;
          valign: center;

          ListBox _format_listbox {
            activate-on-single-click: true;
            selection-mode: none;
            margin-top: 20;
            margin-bottom: 20;
            row-activated => $_row_activated();

            styles [
              "boxed-list-separate",
            ]

            Adw.ButtonRow {
              title: "PDF";
              end-icon-name: "go-next-symbolic";
            }

            Adw.ButtonRow {
              title: "ODT";
              end-icon-name: "go-next-symbolic";
            }

            Adw.ButtonRow {
              title: "HTML";
              end-icon-name: "go-next-symbolic";
            }

            Adw.ButtonRow {
              title: "MD";
              end-icon-name: "go-next-symbolic";
            }
          }
        }
      }

      Adw.StatusPage _parsing {
        paintable: Adw.SpinnerPaintable {
          widget: _parsing;
        };
      }

      Adw.StatusPage _downloading {
        icon-name: "folder-download-symbolic";

        child: ProgressBar _downloading_progress_bar {
          valign: start;
          halign: fill;
          hexpand: true;
        };

        styles [
          "compact",
        ]
      }

      Adw.StatusPage _multi_exporting {
        icon-name: "document-save-as-symbolic";

        child: ProgressBar _multi_export_progress_bar {
          valign: start;
          halign: fill;
          hexpand: true;
        };

        styles [
          "compact",
        ]
      }

      Box _single_exporting {
        orientation: vertical;
        valign: fill;
        vexpand: true;

        Image {
          icon-name: "content-loading-symbolic";
          pixel-size: 120;
          valign: center;
          opacity: 0.7;
          vexpand: true;
        }
      }

      Box _success {
        orientation: vertical;
        valign: center;
        vexpand: true;
        margin-top: 14;
        margin-start: 14;
        margin-end: 14;

        Image {
          icon-name: "check-round-outline-symbolic";
          pixel-size: 100;
          valign: center;
          opacity: 0.7;
          vexpand: true;
          margin-bottom: 20;
        }

        Label _success_label {
          valign: start;
          vexpand: true;
          justify: center;
          wrap: true;
          margin-bottom: 20;
        }
      }

      Box _failure {
        orientation: vertical;
        valign: center;
        vexpand: true;
        margin-start: 14;
        margin-end: 14;

        Image {
          icon-name: "dialog-error-symbolic";
          pixel-size: 60;
          valign: center;
          opacity: 0.7;
          vexpand: true;
          margin-bottom: 20;
        }

        Label _failure_label {
          valign: start;
          vexpand: true;
          justify: center;
          wrap: true;
        }
      }

      Adw.StatusPage _download_failure {
        icon-name: "network-error-symbolic";

        styles [
          "compact",
        ]

        child: Adw.Clamp {
          maximum-size: 300;

          ListBox {
            activate-on-single-click: true;
            selection-mode: none;
            row-activated => $_download_failure_row_activated();

            styles [
              "boxed-list-separate",
            ]

            Adw.ButtonRow _retry_row {
              // Translators: Button
              title: _("Retry");

              styles [
                "suggested-action",
              ]
            }

            Adw.ButtonRow {
              // Translators: Button
              title: _("Export Anyway");
            }
          }
        };
      }
    };
  }
}

