using Gtk 4.0;
using Adw 1;

template $FirstStartPage: Adw.Bin {
  Adw.StatusPage {
    // Translators: Title. Iotas is the application name and shouldn't be translated.
    title: _("Welcome to Iotas");
    icon-name: "text-editor-symbolic";

    Grid {
      row-spacing: 12;
      column-spacing: 12;
      halign: center;

      Label {
        // Translators: Description, introduction help
        label: _("Use the header bar above to…");
        halign: start;
        margin-bottom: 8;

        layout {
          column: "0";
          row: "0";
          column-span: "2";
        }
      }

      Image {
        icon-name: "list-add-symbolic";
        halign: end;

        layout {
          column: "0";
          row: "1";
        }
      }

      Label {
        // Translators: Description, introduction help
        label: _("Add a Note");
        halign: start;

        layout {
          column: "1";
          row: "1";
        }
      }

      Image {
        icon-name: "open-menu-symbolic";
        halign: end;

        layout {
          column: "0";
          row: "2";
        }
      }

      Label {
        // Translators: Description, introduction help
        label: C_("first-start-view", "Sync with Nextcloud Notes");
        halign: start;

        layout {
          column: "1";
          row: "2";
        }
      }
    }
  }
}

