using Gtk 4.0;

template $FontSizeSelector: Box {
  hexpand: true;

  Box {
    spacing: 12;
    margin-start: 18;
    margin-end: 18;

    Button _decrease_button {
      // Translators: Button tooltip
      tooltip-text: _("Zoom Out");
      icon-name: "list-remove-symbolic";
      action-name: "font-size-selector.decrease";

      accessibility {
        // Translators: Button
        label: _("Zoom Out");
      }

      styles [
        "circular",
      ]
    }

    Label _label {
      hexpand: true;
    }

    Button _increase_button {
      // Translators: Button tooltip
      tooltip-text: _("Zoom In");
      icon-name: "list-add-symbolic";
      action-name: "font-size-selector.increase";

      accessibility {
        // Translators: Button
        label: _("Zoom In");
      }

      styles [
        "circular",
      ]
    }
  }
}

