template $FormattingHeaderBar: Adw.BreakpointBin {
  width-request: 360;
  height-request: 40;
  hexpand: true;

  styles [
    "background",
  ]

  Adw.HeaderBar _header_bar {
    show-start-title-buttons: false;
    show-end-title-buttons: false;
    hexpand: true;
    show-back-button: false;

    styles [
      "formatting",
    ]

    [title]
    Box _parent_box {
      spacing: 6;

      Box _base_box {
        spacing: 6;

        MenuButton _heading_menu {
          // Translators: Button tooltip
          tooltip-text: _("Heading");
          icon-name: "heading-symbolic";
          menu-model: heading_menu;
          focus-on-click: false;
        }

        Button {
          // Translators: Button tooltip
          tooltip-text: _("Bold");
          icon-name: "format-text-bold-symbolic";
          action-name: "format.bold";
          focus-on-click: false;
        }

        Button {
          // Translators: Button tooltip
          tooltip-text: _("Italic");
          icon-name: "format-text-italic-symbolic";
          action-name: "format.italic";
          focus-on-click: false;
        }

        Button {
          // Translators: Button tooltip
          tooltip-text: _("Strikethrough");
          icon-name: "format-text-strikethrough-symbolic";
          action-name: "format.strikethrough";
          focus-on-click: false;
        }

        Button {
          // Translators: Button tooltip
          tooltip-text: _("Unordered List");
          icon-name: "view-list-bullet-symbolic";
          action-name: "format.unordered-list";
          focus-on-click: false;
        }

        Button {
          // Translators: Button tooltip
