template $Index: Adw.BreakpointBin {
  name: "Index";
  width-request: 360;
  height-request: 100;

  Adw.Breakpoint _breakpoint {
    condition ("max-width: 700sp")
  }

  Adw.OverlaySplitView _overlay_view {
    collapsed: true;
    sidebar-width-fraction: 0.3;
    max-sidebar-width: 320;
    min-sidebar-width: 240;

    sidebar: $Sidebar _sidebar {};

    content: Adw.ToolbarView {
      hexpand: false;

      [top]
      Stack _header_stack {
        visible-child: _main_header_bar;

        Adw.HeaderBar _main_header_bar {
          show-back-button: false;

          [start]
          Button _content_sidebar_button {
            // Translators: Button tooltip
            tooltip-text: _("Open Categories");
            icon-name: "sidebar-show-symbolic";
            action-name: "index.toggle-sidebar";
          }

          [start]
          Button _new_button {
            // Translators: Button tooltip
            tooltip-text: _("New Note");
            icon-name: "list-add-symbolic";
            action-name: "index.create-note";
          }

          [title]
          Label _title {
            ellipsize: end;

            styles [
              "title",
            ]
          }

          [end]
          $IndexMenuButton _menu_button {}

          [end]
          Button {
            // Translators: Button tooltip
            tooltip-text: _("Search");
            icon-name: "system-search-symbolic";
            action-name: "index.enter-search";
          }

          [end]
          Button {
            // Translators: Button tooltip
            tooltip-text: _("Select Notes");
            icon-name: "selection-mode-symbolic";
            action-name: "index.select-notes";
          }
        }

        $IndexSearchHeaderBar _search_header_bar {}

        $SelectionHeaderBar _selection_header_bar {}
      }

      [top]
      Adw.Banner _offline_banner {
        // Translators: Description
        title: _("Server connection offline");
      }

      [top]
      Adw.Banner _app_id_change_reauthenticate_banner {
        // Translators: Description
        title: _(
          "Due to behind-the-scenes changes (a new app id) Iotas needs to reauthenticate with your Nextcloud server"
        );

        // Translators: Button
        button-label: _("Authenticate");

        button-clicked => $_on_reauthenticate();
      }

      [top]
      Adw.Banner _generic_reauthenticate_banner {
        // Translators: Description
        title: _("The authentication token for sync with Nextcloud Notes could not be retrieved");

        // Translators: Button
        button-label: _("Authenticate");

        button-clicked => $_on_reauthenticate();
      }

      [top]
      Adw.Banner _misc_banner {
        // Translators: Button
        button-label: _("Dismiss");
        button-clicked => $_on_misc_banner_button();
      }

      content: Adw.ToastOverlay _toast_overlay {
        child: Stack _stack {
          visible-child: _note_list_scroll;

          $FirstStartPage _first_start {}

          Adw.StatusPage _loading {
            paintable: Adw.SpinnerPaintable {
              widget: _loading;
            };
          }

          Adw.StatusPage _empty {
            // Translators: Description, help
            title: _("Note List Empty");
            icon-name: "text-justify-fill-symbolic";
          }

          Adw.StatusPage _search_info {
            // Translators: Description, help
            title: _("Enter Search Term");
            icon-name: "folder-saved-search-symbolic";
          }

          Adw.StatusPage _search_empty {
            // Translators: Description, help
            title: _("No Search Results");
            icon-name: "folder-saved-search-symbolic";
          }

          ScrolledWindow _note_list_scroll {
            vexpand: true;
            edge-overshot => $_on_edge_overshot();

            Adw.Clamp {
              maximum-size: 500;

              $IndexNoteList _note_list {}
            }
          }
        };
      };
    };
  }
}

