  name: "OutlineDialog";

  Box {
    orientation: vertical;

    Stack _header_stack {
      visible-child: _main_headerbar;

      Adw.HeaderBar _main_headerbar {
        styles [
          "flat",
        ]

        [title]
        Label {
          // Translators: Title
          label: _("Outline");
          ellipsize: end;

          styles [
            "title",
          ]
        }
      }

      Adw.HeaderBar _filter_headerbar {
        styles [
          "flat",
          "list-matched",
        ]

        [title]
        Adw.Clamp {
          maximum-size: 265;
          hexpand: true;

          SearchEntry _filter_entry {
            hexpand: true;
            search-delay: 0;
            activate => $_on_entry_activate();
