      }

      Adw.SwitchRow _markdown_use_monospace_font {
        // Translators: Title
        title: _("Render Using Monospace Font");
        action-name: "settings.markdown-use-monospace-font";
      }

      Adw.SpinRow _markdown_monospace_font_ratio {
