    icon-name: "drive-harddisk-symbolic";

    Adw.PreferencesGroup {
      Adw.ActionRow _connect_sync_row {
        // Translators: Title
        title: _("Connect Nextcloud");

        // Translators: Description, preference
        subtitle: _("Establish sync with Nextcloud Notes");

        selectable: false;

        Button {
          // Translators: Button
          label: _("Log In");
          halign: start;
          valign: center;
          clicked => $_connect_nextcloud();
        }
      }

      Adw.ActionRow _disconnect_sync_row {
        // Translators: Title
        title: _("Disconnect Nextcloud");

